// Default: fictional demo. No product event; platform usage may apply.
// For an authorized dataset, replace this object with:
// {inputMode: "dataset", datasetId: "YOUR_DATASET_ID", corpusId: "my-help-center", completeSnapshot: false}
// A dataset or inline run costs $0.50 per completed report plus platform usage.
// Partial/incremental inputs remain review-only. Set completeSnapshot:true only
// for an explicitly confirmed full authoritative source snapshot.
// Compare only against a baseline whose operations the destination accepted.
return [{json:{inputMode:"demo",completeSnapshot:false,chunkChars:250,overlapChars:50}}];

const input = $input.first().json;
if (!input || typeof input !== "object" || Array.isArray(input)) throw new Error("Expected one Actor input object.");
const mode = input.inputMode ?? "demo";
if (!["demo", "inline", "dataset"].includes(mode)) throw new Error("Choose demo, inline or dataset inputMode.");
if (input.completeSnapshot !== undefined && typeof input.completeSnapshot !== "boolean") {
  throw new Error("completeSnapshot must be an explicit boolean. Leave it false for partial or incremental data.");
}
if (input.previousManifestStoreId !== undefined && (typeof input.previousManifestStoreId !== "string" || !input.previousManifestStoreId.trim())) {
  throw new Error("previousManifestStoreId must identify a baseline already accepted by the destination, or be omitted.");
}
// Never infer a full snapshot from a successful crawler run or dataset presence.
return [{json:{...input,inputMode:mode,completeSnapshot:input.completeSnapshot === true}}];

const run = $input.first().json?.data;
if (!run || typeof run !== "object" || Array.isArray(run) || typeof run.id !== "string" || !run.id.trim()) {
  throw new Error("Apify did not return a run ID. The start request may have succeeded. Inspect your recent Apify runs before starting another paid report; never automatically retry the POST.");
}
if (!["READY", "RUNNING", "SUCCEEDED"].includes(run.status)) {
  throw new Error("Apify run "+run.id+" returned status "+String(run.status)+". Inspect that exact run in Apify Console; do not start another paid report automatically.");
}
return [{json:{id:run.id}}];

const run = $input.first().json?.data;
const originalId = $("Capture run ID").first().json.id;
if (!run || typeof run !== "object" || Array.isArray(run) || run.id !== originalId) {
  throw new Error("Could not verify the response for Apify run "+originalId+". Inspect that exact run; do not repeat the paid POST.");
}
if (run.status !== "SUCCEEDED") {
  throw new Error("Apify run "+originalId+" is "+String(run.status)+" after the bounded wait. It may still be active. Inspect that exact run in Apify Console or GET /v2/actor-runs/"+originalId+" before deciding whether another paid report is needed; do not automatically retry the POST.");
}
if (typeof run.defaultKeyValueStoreId !== "string" || !run.defaultKeyValueStoreId.trim() || typeof run.defaultDatasetId !== "string" || !run.defaultDatasetId.trim()) {
  throw new Error("Successful Apify run "+originalId+" is missing output storage IDs. Inspect that exact run; do not repeat the paid POST.");
}
return [{json:run}];

const status = $input.first().json;
const run = $("Require successful run").first().json;
if (!status || typeof status !== "object" || Array.isArray(status) || status.status !== "COMPLETE") {
  throw new Error("Report for Apify run "+run.id+" is not COMPLETE; do not consume operations or update a baseline. Inspect that exact run; do not repeat the paid POST.");
}
// The Actor writes COMPLETE only after saving outputs and confirming billing,
// or after its explicitly unbilled fictional demo. Do not infer completion from SUCCEEDED alone.
return [{json:{...run,completion:status}}];

const run = $("Require complete report").first().json;
const input = $("Validate input").first().json;
const qa = $("Read QA").first().json;
const manifest = $("Read manifest").first().json;
const ops = $input.first().json.body;
const isObject = value => value !== null && typeof value === "object" && !Array.isArray(value);
const isCount = value => Number.isSafeInteger(value) && value >= 0;
const isText = value => typeof value === "string" && value.trim().length > 0;
const isDemo = input.inputMode === "demo";
const corpusId = isDemo ? "demo" : (input.corpusId ?? "knowledge-base");
const countFields = ["inputRows", "acceptedDocuments", "duplicateRowsRemoved", "rejectedRows", "unchangedDocuments", "totalChunks", "upsertCount", "deleteCount"];
if (!isObject(qa) || countFields.some(key => !isCount(qa[key])) || !Array.isArray(qa.issues)
    || typeof qa.completeSnapshot !== "boolean" || typeof qa.deletionEnabled !== "boolean"
    || qa.issues.length !== qa.rejectedRows || qa.inputRows > 500 || qa.totalChunks > 8000
    || qa.deleteCount > 8000 || qa.upsertCount > qa.totalChunks
    || qa.acceptedDocuments + qa.duplicateRowsRemoved + qa.rejectedRows !== qa.inputRows
    || qa.unchangedDocuments > qa.acceptedDocuments || qa.totalChunks < qa.acceptedDocuments) {
  throw new Error("Malformed or inconsistent QA report; no downstream handoff or baseline update is allowed.");
}
const issueRows = new Set();
for (const issue of qa.issues) {
  if (!isObject(issue) || !isCount(issue.row) || issue.row >= qa.inputRows || !isText(issue.reason) || issueRows.has(issue.row)) {
    throw new Error("Malformed QA issue list; no downstream handoff is allowed.");
  }
  issueRows.add(issue.row);
}
if (!isObject(manifest) || manifest.schemaVersion !== 1 || !isObject(manifest.config)
    || manifest.config.corpus !== corpusId || !isObject(manifest.documents)
    || typeof manifest.complete !== "boolean" || typeof run.completion.baselineEligible !== "boolean"
    || manifest.complete !== qa.completeSnapshot || (!isDemo && manifest.complete !== run.completion.baselineEligible)) {
  throw new Error("Manifest and completion status do not agree on the corpus or complete snapshot; keep the previous baseline.");
}
if (!isDemo && input.completeSnapshot !== true && manifest.complete) {
  throw new Error("A partial input was reported as a complete snapshot; keep the previous baseline.");
}
for (const record of [qa, run.completion]) {
  if ((record.downstreamReady !== undefined && typeof record.downstreamReady !== "boolean")
      || (record.approvalStatus !== undefined && !["READY", "BLOCKED", "REVIEW_REQUIRED"].includes(record.approvalStatus))
      || (record.approvalReasons !== undefined && (!Array.isArray(record.approvalReasons) || record.approvalReasons.some(reason => !isText(reason))))) {
    throw new Error("Malformed Actor approval fields; no downstream handoff is allowed.");
  }
}
const hasApproval = record => typeof record.downstreamReady === "boolean"
  && ["READY", "BLOCKED", "REVIEW_REQUIRED"].includes(record.approvalStatus)
  && Array.isArray(record.approvalReasons) && record.approvalScope === "SUPPLIED_RECORDS_ONLY";
const actorApprovalAvailable = hasApproval(qa) && hasApproval(run.completion);
if (!Array.isArray(ops) || ops.length > 16000 || ops.length !== qa.upsertCount + qa.deleteCount
    || (run.completion.operationCount !== undefined && run.completion.operationCount !== ops.length)) {
  throw new Error("Expected a complete JSON array of chunk operations matching the report counts; no downstream handoff is allowed.");
}
const chunkIds = new Set();
for (const op of ops) {
  if (!isObject(op) || !["UPSERT", "DELETE"].includes(op.operation) || !isText(op.chunkId)
      || !isText(op.source) || op.corpusId !== corpusId || chunkIds.has(op.chunkId)
      || (op.operation === "UPSERT" && !isText(op.text))) {
    throw new Error("Malformed, duplicate or foreign-corpus chunk operation; no downstream handoff is allowed.");
  }
  chunkIds.add(op.chunkId);
}
const upserts = ops.filter(op => op.operation === "UPSERT");
const deleteSuggestions = ops.filter(op => op.operation === "DELETE");
if (upserts.length !== qa.upsertCount || deleteSuggestions.length !== qa.deleteCount
    || (deleteSuggestions.length > 0 && (!qa.deletionEnabled || !manifest.complete || !input.previousManifestStoreId))) {
  throw new Error("Chunk operations do not match QA counts or deletion eligibility; keep the previous baseline.");
}
// COMPLETE means report production finished. Acceptance and destination delivery
// are separate states. Optional stricter Actor flags can only close this gate.
const qaAccepted = qa.rejectedRows === 0 && qa.issues.length === 0 && qa.acceptedDocuments > 0;
const blockedReasons = [];
if (!qaAccepted) blockedReasons.push("QA rejected source rows or accepted no documents; repair and review the input before indexing.");
if (isDemo) blockedReasons.push("Fictional demo output is for preview only.");
if (input.completeSnapshot !== true || !manifest.complete) blockedReasons.push("Partial or incremental data is review-only; automatic handoff requires a complete authoritative snapshot.");
if (!actorApprovalAvailable) blockedReasons.push("ACTOR_APPROVAL_UNAVAILABLE: This Actor output lacks the explicit approval contract; review only.");
if (actorApprovalAvailable && [qa, run.completion].some(record => record.downstreamReady !== true || record.approvalStatus !== "READY" || record.approvalReasons.length > 0)) {
  blockedReasons.push("The Actor explicitly withheld downstream approval.");
}
const downstreamReady = blockedReasons.length === 0;
return [{json:{
  runId:run.id,
  storeId:run.defaultKeyValueStoreId,
  reportComplete:true,
  qaAccepted,
  actorApprovalAvailable,
  downstreamReady,
  blockedReasons,
  qa,
  // Only these top-level arrays are a candidate handoff. DELETEs remain suggestions.
  upserts:downstreamReady ? upserts : [],
  deleteSuggestions:downstreamReady ? deleteSuggestions : [],
  review:{upserts,deleteSuggestions,note:"Inspection only. Do not wire this review object to a destination."},
  baseline:{
    previousManifestStoreId:input.previousManifestStoreId ?? null,
    candidateManifestStoreId:downstreamReady ? run.defaultKeyValueStoreId : null,
    eligible:downstreamReady,
    commitAllowed:false,
    updated:false,
    requiresDestinationAcknowledgement:true,
    note:"Keep the previous baseline until the destination confirms all UPSERTs and reviewed DELETEs were applied. This workflow never persists a new baseline."
  },
  note:"This recipe produces a reviewed handoff candidate only. It does not generate embeddings, write to a vector database, apply DELETE suggestions or acknowledge destination acceptance."
}}];
